BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off;
WITH q AS(SELECT baseline_version,industry_level,count(*) nodes FROM core_serving.wealth_sector_hierarchy GROUP BY baseline_version,industry_level)
SELECT jsonb_build_object('section','fixed_hierarchy','as_of',current_timestamp,'data',jsonb_agg(to_jsonb(q) ORDER BY industry_level)) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),m AS MATERIALIZED(SELECT m.trade_date,h.industry_level,m.con_code,h.root_sector_code,h.parent_sector_code FROM core_serving.dc_member m JOIN core_serving.wealth_sector_hierarchy h ON h.sector_code=m.ts_code WHERE m.trade_date IN(DATE '2026-10-29',DATE '2026-10-30')),ds AS(SELECT DISTINCT trade_date,industry_level FROM m),q AS(SELECT ds.trade_date,ds.industry_level,count(DISTINCT a.ts_code) eligible_codes,count(DISTINCT m.con_code) mapped_codes FROM ds CROSS JOIN base a LEFT JOIN m ON m.trade_date=ds.trade_date AND m.industry_level=ds.industry_level AND m.con_code=a.ts_code GROUP BY ds.trade_date,ds.industry_level),leaf AS MATERIALIZED(SELECT con_code,count(DISTINCT root_sector_code) root_count,count(DISTINCT parent_sector_code) parent_count FROM m WHERE trade_date=DATE '2026-10-30' AND industry_level=3 GROUP BY con_code),r AS(SELECT count(*) codes,count(*) FILTER(WHERE leaf.con_code IS NOT NULL) leaf_mapped,count(*) FILTER(WHERE leaf.root_count=1 AND leaf.parent_count=1) unique_root_and_parent,count(*) FILTER(WHERE leaf.root_count>1 OR leaf.parent_count>1) conflicting_leaf_ancestors FROM base a LEFT JOIN leaf ON leaf.con_code=a.ts_code),missing AS(SELECT a.ts_code,a.name FROM base a LEFT JOIN leaf ON leaf.con_code=a.ts_code WHERE leaf.con_code IS NULL ORDER BY a.ts_code LIMIT 20)
SELECT jsonb_build_object('section','retained_scope_members','as_of',current_timestamp,'direct_level_counts',(SELECT jsonb_agg(to_jsonb(q) ORDER BY trade_date,industry_level) FROM q),'leaf_ancestor_counts',(SELECT to_jsonb(r) FROM r),'missing_leaf_samples',(SELECT jsonb_agg(to_jsonb(missing)) FROM missing));
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),v AS MATERIALIZED(SELECT ts_code,close,total_mv,total_share,pe_ttm,pb,ps_ttm,dv_ttm FROM core_serving.equity_daily_basic WHERE trade_date=DATE '2026-10-30'),q AS(SELECT count(*) eligible_codes,count(v.ts_code) quote_codes,count(*) FILTER(WHERE v.close>0 AND v.total_mv>0 AND v.total_share>0) valid_basic_inputs,count(v.pe_ttm) pe_nonnull,count(v.pb) pb_nonnull,count(v.ps_ttm) ps_nonnull,count(v.dv_ttm) dv_nonnull FROM base a LEFT JOIN v ON v.ts_code=a.ts_code)
SELECT jsonb_build_object('section','retained_scope_valuation','as_of',current_timestamp,'data',to_jsonb(q)) FROM q;
COMMIT;
